function addDays(iso, n){ var d=new Date(iso+'T00:00:00Z'); d.setUTCDate(d.getUTCDate()+n); return d.toISOString().slice(0,10); }
function diffDays(a, b){ var da=new Date(a+'T00:00:00Z'), db=new Date(b+'T00:00:00Z'); return Math.round((db-da)/86400000); }
function weekday(iso){ var d=new Date(iso+'T00:00:00Z'); return ['周日','周一','周二','周三','周四','周五','周六'][d.getUTCDay()]; }
function daysInMonth(y, m){ return new Date(Date.UTC(y, m, 0)).getUTCDate(); }
var EXPORTS={addDays:addDays,diffDays:diffDays,weekday:weekday,daysInMonth:daysInMonth};


function rngFactory(seed){ var s=(seed>>>0)||1; return function(){ s=(s*1664525+1013904223)>>>0; return s/4294967296; }; }

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.CalendarForgePure = EXPORTS; }
